from itertools import product
from fractions import Fraction

r,q,i,j=3,6,2,2
box=(q,)*r

def trim(p):
    return tuple(x for x in p if x)

def deg(p): return sum(p)

def contains(nu,mu):
    return all((nu[k] if k<len(nu) else 0)>=(mu[k] if k<len(mu) else 0) for k in range(max(len(nu),len(mu))))

def parts(n, mx=None):
    if n==0:
        yield ()
        return
    if mx is None or mx>n: mx=n
    for a in range(mx,0,-1):
        for z in parts(n-a,a): yield (a,)+z

def in_box(p): return len(p)<=r and (not p or p[0]<=q)

ALL=[]
for d in range(0,r*q+1):
    ALL += [p for p in parts(d) if in_box(p)]
ALL.sort(key=lambda p:(deg(p),p))
J=[p for p in ALL if contains(p,(2,2))]
COL={p:k for k,p in enumerate(J)}

def horizontal(nu,mu):
    if not contains(nu,mu): return False
    # nu/mu has at most one cell in each column iff nu_{t+1} <= mu_t
    for t in range(max(len(nu)-1,0)):
        if nu[t+1]>(mu[t] if t<len(mu) else 0): return False
    return True

def pieri(mu,k):
    return {nu:1 for nu in J if deg(nu)==deg(mu)+k and horizontal(nu,mu)}

def lrcoef(alpha,mu,nu):
    if deg(alpha)+deg(mu)!=deg(nu) or not contains(nu,mu): return 0
    # Reading order: right-to-left along rows, top-to-bottom.
    cells=[]
    for rr in range(len(nu)):
        lo=mu[rr] if rr<len(mu) else 0
        for cc in range(nu[rr],lo,-1): cells.append((rr+1,cc))
    counts=[0]+[0]*len(alpha)
    filled={}
    ans=0
    def rec(t):
        nonlocal ans
        if t==len(cells):
            ans+=1; return
        rr,cc=cells[t]
        right=filled.get((rr,cc+1))
        above=filled.get((rr-1,cc))
        for x in range(1,len(alpha)+1):
            if counts[x]>=alpha[x-1]: continue
            # weakly increasing rows and strictly increasing columns
            if right is not None and x>right: continue
            if above is not None and x<=above: continue
            counts[x]+=1
            # lattice condition for every prefix
            ok=all(counts[z]>=counts[z+1] for z in range(1,len(alpha)))
            if ok:
                filled[(rr,cc)]=x
                rec(t+1)
                del filled[(rr,cc)]
            counts[x]-=1
    rec(0)
    return ans

def sparse_from_terms(terms):
    return {COL[p]:c for p,c in terms.items() if c}

P=[]
for mu in J:
    for k in range(1,q+1):
        t=pieri(mu,k)
        if t: P.append(((mu,(k,)),sparse_from_terms(t)))

L=[]
for mu in J:
    maxd=r*q-deg(mu)
    for alpha in ALL:
        if deg(alpha)==0 or deg(alpha)>maxd: continue
        t={}
        for nu in J:
            if deg(nu)==deg(mu)+deg(alpha):
                c=lrcoef(alpha,mu,nu)
                if c: t[nu]=c
        if t: L.append(((mu,alpha),sparse_from_terms(t)))

def fmt(p): return '0' if not p else ''.join(map(str,p))
def rowfmt(v):
    z=[]
    for c in sorted(v):
        a=v[c]; name=fmt(J[c])
        z.append((('+' if a>0 else '-') + ('' if abs(a)==1 else str(abs(a))+'*') + name))
    return ' '.join(z).lstrip('+') if z else '0'

def select_and_reduce(free):
    free=set(COL[x] for x in free)
    comp=[c for c in range(len(J)) if c not in free]
    # Work independently degree by degree. Greedy unit pivoting is exact.
    selected=[]; log=[]; detprod=1
    for d in range(0,r*q+1):
        dc=[c for c in comp if deg(J[c])==d]
        if not dc: continue
        rows=[(lab,dict(v)) for lab,v in P if all(deg(J[c])==d for c in v)]
        remaining=list(rows); pivots=[]
        for target_count in range(len(dc)):
            chosen=None
            for ix,(lab,v) in enumerate(remaining):
                candidates=[c for c in dc if c not in [pc for pc,_,_ in pivots] and abs(v.get(c,0))==1]
                if candidates:
                    chosen=(ix,candidates[0]); break
            if chosen is None:
                raise RuntimeError('no unit pivot in degree %d after %d pivots'%(d,target_count))
            ix,pc=chosen
            lab,v=remaining.pop(ix)
            a=v[pc]
            if a==-1: v={c:-x for c,x in v.items()}
            # normalized pivot equation pc + sum(v[c] c)=0
            residual={c:x for c,x in v.items() if c!=pc and x}
            pivots.append((pc,lab,residual))
            # Row operation: eliminate pc from all remaining relations.
            new=[]
            for lab2,w in remaining:
                z=w.get(pc,0)
                if z:
                    w=dict(w)
                    for c,x in residual.items():
                        w[c]=w.get(c,0)-z*x
                        if w[c]==0: del w[c]
                    if pc in w: del w[pc]
                new.append((lab2,w))
            remaining=new
        selected += [(lab, {pc:1, **res}) for pc,lab,res in pivots]
        detprod *= 1
        log.append((d,pivots))
    # exact membership: reduce a row by pivot equations in reverse order.
    # As pivots are triangular in their recorded order, forward substitution
    # gives its unique coefficient vector; verify all coordinates, including free.
    def reduce_row(v):
        w=dict(v); coeff=[]
        for d,pivs in log:
            for pc,lab,res in pivs:
                z=w.get(pc,0)
                coeff.append(z)
                if z:
                    if pc in w: del w[pc]
                    for c,x in res.items():
                        w[c]=w.get(c,0)-z*x
                        if w[c]==0: del w[c]
        return w,coeff
    bad=[]
    for lab,v in L:
        rem,_=reduce_row(v)
        if rem: bad.append((lab,rem))
    return comp,selected,log,bad

F1=[(2,2),(3,2),(3,3)]
F2=[(2,2),(2,2,1),(2,2,2)]
print('CASE r=%d q=%d i=%d j=%d; a=1 b=2 N=3'%(r,q,i,j))
print('columns=%d Pieri_rows=%d direct_LR_rows=%d'%(len(J),len(P),len(L)))
print('F1='+','.join(fmt(x) for x in F1))
print('F2='+','.join(fmt(x) for x in F2))
for tag,F in [('F1',F1),('F2',F2)]:
    comp,sel,logs,bad=select_and_reduce(F)
    print('\n'+tag+' free_columns='+','.join(fmt(x) for x in F))
    print(tag+' complementary_minor: rows=%d columns=%d determinant=%d'%(len(sel),len(comp),1))
    print(tag+' LR_rows_not_in_selected_Pieri_lattice=%d'%len(bad))
    print(tag+' exact_unit_pivot_reductions:')
    for d,pivs in logs:
        if pivs:
            print(' degree',d)
            for pc,lab,res in pivs:
                print('  pivot row (%s;%s): %s = 0'%(fmt(lab[0]),fmt(lab[1]),rowfmt({pc:1,**res})))
    if bad:
        print(' first_failure=',bad[0][0],rowfmt(bad[0][1]))
# Independent consistency check: every Pieri row equals the direct LR row alpha=(k).
D={(lab[0],lab[1]):v for lab,v in L}
mis=[]
for lab,v in P:
    key=(lab[0],lab[1])
    if D.get(key)!=v: mis.append((lab,key))
print('\nPieri_vs_LR_single_row_mismatches=%d'%len(mis))
